//! Shared by the engine's benchmarks: the target-scale synthetic fixtures (40 swimlanes, about 80,000 files), generated by
//! `xtask::fixtures::generate` when `target/fixtures/target/manifest.json` is missing. The benchmarks measure at design
//! scale, never on toy data (`lanekeeper-performance`).
#![allow(dead_code, clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::{Path, PathBuf};

/// `$CARGO_TARGET_DIR`, or the workspace's `target`.
pub fn target_dir() -> PathBuf {
    std::env::var_os("CARGO_TARGET_DIR").map_or_else(
        || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target"),
        PathBuf::from,
    )
}

/// The target-scale fixtures: `$LK_FIXTURES_DIR`, or `target/fixtures/target`, generated here when absent. It needs `git`
/// on the PATH, as the generator does.
pub fn fixtures() -> PathBuf {
    let base = std::env::var_os("LK_FIXTURES_DIR")
        .map_or_else(|| target_dir().join("fixtures/target"), PathBuf::from);
    if !base.join("manifest.json").is_file() {
        xtask::fixtures::generate(&xtask::fixtures::Config {
            scale: xtask::fixtures::Scale::Target,
            seed: xtask::fixtures::DEFAULT_SEED,
            out: base.clone(),
        })
        .unwrap_or_else(|e| {
            panic!(
                "cannot generate the target-scale fixtures at {}: {e}",
                base.display()
            )
        });
    }
    base
}

/// The first swimlane's directory (sorted by name).
pub fn swimlane_one() -> PathBuf {
    let nfs = fixtures().join("nfs");
    let mut swimlanes: Vec<PathBuf> = fs::read_dir(&nfs)
        .unwrap()
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.is_dir())
        .collect();
    swimlanes.sort();
    swimlanes.into_iter().next().expect("a swimlane")
}

/// Every file below `dir` whose name ends with one of `suffixes`, sorted.
pub fn files_with_suffix(dir: &Path, suffixes: &[&str]) -> Vec<PathBuf> {
    fn walk(dir: &Path, suffixes: &[&str], out: &mut Vec<PathBuf>) {
        let mut entries: Vec<PathBuf> = fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).collect();
        entries.sort();
        for path in entries {
            if path.is_dir() {
                walk(&path, suffixes, out);
            } else if path
                .file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| suffixes.iter().any(|s| n.ends_with(s)))
            {
                out.push(path);
            }
        }
    }
    let mut out = Vec::new();
    walk(dir, suffixes, &mut out);
    out
}

/// The largest YAML file of swimlane 1 (a 6,000-line file), as text.
pub fn big_yaml() -> (PathBuf, String) {
    let best = files_with_suffix(&swimlane_one(), &[".yml", ".yaml"])
        .into_iter()
        .map(|p| {
            let text = fs::read_to_string(&p).unwrap();
            (text.lines().count(), p, text)
        })
        .max_by_key(|(lines, _, _)| *lines)
        .expect("a YAML file");
    assert!(
        (5_900..=6_600).contains(&best.0),
        "the largest YAML file has {} lines: not a 6,000-line file",
        best.0
    );
    (best.1, best.2)
}
